2	
3	/**
4	 * Derives an owner's numeric 'membershipLevel', assigned on create. Kept out of
5	 * {@link OwnerMapper} so MapStruct does not mistake it for an implicit property
6	 * mapping method.
7	 */
8	public final class MembershipLevelResolver {
9	
10	    /** The highest level attainable on create; level 4 is reserved for tenure. */
11	    private static final int MAX_LEVEL = 3;
12	
13	    private MembershipLevelResolver() {
14	    }
15	
16	    /**
17	     * Returns the membership level for an owner. Starts at 1, gains 1 when an
18	     * email is present (non-blank), gains 1 when the owner's name was unique on
19	     * create ({@code namesakeCount} is 0), and is capped at 3.
20	     *
21	     * @param email         the owner's email, may be {@code null}
22	     * @param namesakeCount the owner's namesake count, may be {@code null}
23	     * @return the membership level, between 1 and 3 inclusive
24	     */
25	    public static int deriveMembershipLevel(String email, Integer namesakeCount) {
26	        int level = 1;
27	        if (email != null && !email.isBlank()) {
28	            level++;
29	        }
30	        if (namesakeCount != null && namesakeCount == 0) {
31	            level++;
32	        }
33	        return Math.min(level, MAX_LEVEL);
34	    }
35	}
